UPDATE public.spots SET access = '{"boat": true, "ramp": "Yorkeys Knob is the major public facility — a six-lane ramp with three floating walkways, breakwaters, a dredged basin and queuing beaches", "parking": "135 car-trailer bays and 63 single car parks at Yorkeys Knob", "facilities": ["Six-lane boat ramp", "Floating walkways", "Amenities block", "Queuing beaches"], "notes": "The heavy-tackle marlin grounds are well offshore on the outer reef, so this is a boat fishery — most anglers go by charter from Cairns rather than trailering. Yorkeys Knob was rebuilt in a $22.4m joint project completed in September 2023. Under the standard Queensland arrangement, Maritime Safety Queensland owns the in-water infrastructure and Cairns Regional Council manages the facility.", "sourceUrl": "https://www.msq.qld.gov.au/boating-facilities"}'::jsonb, updated_at = now() WHERE slug = 'cairns-black-marlin';
UPDATE public.spots SET access = '{"shore": true, "boat": true, "ramp": "Buffalo Creek is the main northern-suburbs ramp; the NT Government publishes an interactive boat ramp finder covering all Territory ramps", "parking": "Car park at Buffalo Creek with lighting and CCTV, plus a secure compound", "facilities": ["Boat ramp", "Toilets", "Lit car park with CCTV", "Secure compound"], "notes": "The secure compound at Buffalo Creek is now free to use, but you need to phone for an access code before arriving — worth doing in advance. Saltwater crocodiles are present throughout Darwin Harbour and its creeks; follow the NT Government''s Be Crocwise advice and never clean fish or enter the water at the ramp.", "sourceUrl": "https://nt.gov.au/marine/for-all-harbour-and-boat-users/ramps-wharves-and-moorings/find-a-boat-ramp"}'::jsonb, updated_at = now() WHERE slug = 'darwin-harbour-barramundi';
UPDATE public.spots SET access = '{"shore": true, "boat": true, "ramp": "Yarrawonga Common boat launch, reached via Cullens Road in Yarrawonga Regional Park — extended and duplicated by Moira Shire with improved traffic access and parking", "parking": "Car park at the Yarrawonga Common entrance off Cullens Road", "facilities": ["Boat ramp", "Picnic tables", "Pit toilets", "Walking track"], "notes": "IMPORTANT CLOSURE: the stretch from Yarrawonga Weir down to the Tocumwal Road Bridge is closed to ALL forms of fishing from 1 September to 30 November. That is broader than the general Murray cod closed season, which applies to the species rather than the water — on this stretch you may not fish at all during those months. This is a border river, so whether you need a NSW or Victorian licence depends on which bank you fish from.", "sourceUrl": "https://vfa.vic.gov.au/recreational-fishing/fishing-locations/inland-angling-guide/special-articles/murray-river-nsw"}'::jsonb, updated_at = now() WHERE slug = 'murray-river-cod-yarrawonga';
